SELECT '100', '수출입명세코드', '20200101000000', '99991231235959', 'Y', '문서분류', '14', 'SYSTEM', '20250115120000' FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM CSPD111TI WHERE AI_INPT_GRP_CD = '100');

-- 2. 잘못 등록된 04(원산지→C/O) 보정 → 04=Certificate, 06=C/O
UPDATE CSPD112TI
   SET AI_INPT_CMN_CD_NM = '증명서',
       AI_INPT_CMN_CD_ENG_NM = 'Certificate',
       AI_INPT_RMRK_TXT = 'CERT',
       AI_INPT_INTF_ITM_NM = 'Certificate',
       LST_DB_CHG_ID = 'SYSTEM',
       LST_DB_CHG_DTM = '20250115120000'
 WHERE AI_INPT_GRP_CD = '100'
   AND AI_INPT_CMN_CD = '04'
   AND AI_INPT_INTF_ITM_NM = 'C/O';

